-- Expansão do catálogo acadêmico e metadados de embalagem do SQLite da raspagem.
-- Os vínculos do SQLite são candidatos de catálogo. As receitas do planejador
-- usam produtos explícitos com preço de referência e unidade conferida.

alter table public.stores add column selectable boolean not null default true,
  add column selection_order integer not null default 100;
update public.stores set selectable=false
where lower(btrim(name)) in ('supermercado exemplo','epa','epa supermercados','supermercados epa');

insert into public.stores(name,selection_order) values
  ('Supermercados BH', 1),
  ('Villefort', 2),
  ('Verdemar', 3),
  ('Assaí', 4),
  ('Supernosso', 5),
  ('Carrefour', 6),
  ('Mart Minas', 7),
  ('Prata', 8)
on conflict (name) do update set selectable=true, selection_order=excluded.selection_order;

