) v(id,category,name,normalized_name,quantity,unit,truncated,review,active,expiration_days)
join public.categories c on c.name=v.category
on conflict (normalized_name) do update set
  package_quantity=coalesce(products.package_quantity,excluded.package_quantity),
  unit=coalesce(products.unit,excluded.unit),
  default_expiration_days=coalesce(products.default_expiration_days,excluded.default_expiration_days);

