alter table public.recipes add column preferences jsonb;

insert into public.recipes(id,name,preparation_minutes,servings,vegetarian,preparation_steps,preferences) values
  ('arroz-com-feijao', 'Arroz com feijão', 40, 2, true, '["Deixe o feijão de molho e descarte a água do remolho. Cozinhe em água limpa até os grãos ficarem macios.","Cozinhe o arroz à parte. Refogue a cebola no óleo e misture ao feijão.","Sirva o feijão com o caldo sobre o arroz."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Fogão"],"goals":["Refeição de família","Conforto e sabor"]}'::jsonb),
  ('frango-grelhado', 'Frango grelhado com tomate', 25, 2, false, '["Seque os filés, aqueça a frigideira e grelhe com parte do óleo até que o centro do frango atinja 74 °C.","Em outra panela, refogue a cebola e o tomate picado até formar um molho rústico.","Sirva o molho sobre os filés."]'::jsonb, '{"restrictions":["Peixe","Glúten"],"appliances":["Fogão"],"goals":["Rico em proteína","Refeição prática"]}'::jsonb),
  ('mingau-de-aveia', 'Mingau simples de aveia', 10, 2, true, '["Misture a aveia e o leite em uma panela fria.","Aqueça em fogo baixo e mexa até os flocos ficarem macios e o mingau engrossar."]'::jsonb, '{"restrictions":["Peixe","Vegetariano"],"appliances":["Fogão"],"goals":["Lanche caseiro","Conforto e sabor"]}'::jsonb),
  ('omelete-simples', 'Omelete simples', 12, 2, true, '["Refogue a cebola finamente picada em uma frigideira com óleo.","Bata os ovos, acrescente à frigideira e cozinhe dos dois lados até firmar."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Glúten"],"appliances":["Fogão"],"goals":["Refeição prática","Rico em proteína"]}'::jsonb),
  ('arroz-cremoso-brocolis', 'Arroz cremoso com brócolis', 30, 2, true, '["Refogue a cebola, adicione o arroz e cozinhe em água até ficar macio.","Acrescente o brócolis picado e o leite. Mexa em fogo baixo até ficar cremoso e o brócolis ficar macio."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Glúten"],"appliances":["Fogão"],"goals":["Conforto e sabor","Refeição de família"]}'::jsonb),
  ('lentilha-tomate', 'Ensopado de lentilha e tomate', 35, 2, true, '["Refogue a cebola e a cenoura. Acrescente o tomate picado e deixe desmanchar.","Junte a lentilha lavada e cubra com água. Cozinhe até a lentilha ficar macia e o caldo encorpar."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Fogão"],"goals":["Refeição leve","Conforto e sabor"]}'::jsonb),
  ('macarrao-brocolis', 'Macarrão com brócolis e cebola', 25, 2, true, '["Cozinhe o macarrão. Nos minutos finais, cozinhe o brócolis na mesma água.","Refogue a cebola separadamente. Escorra a massa e o brócolis e misture tudo com um pouco da água do cozimento."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano"],"appliances":["Fogão"],"goals":["Refeição prática","Diferente"]}'::jsonb),
  ('macarrao-lentilha', 'Macarrão com molho de lentilha', 35, 2, true, '["Cozinhe a lentilha até ficar macia e escorra.","Refogue a cebola, adicione a lentilha e o molho de tomate. Deixe apurar e sirva sobre o macarrão cozido."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano"],"appliances":["Fogão"],"goals":["Refeição de família","Rico em proteína"]}'::jsonb),
  ('arroz-carreteiro', 'Arroz de panela com carne moída', 35, 2, false, '["Refogue a cebola com a carne moída, mexendo até que a carne esteja totalmente cozida.","Acrescente o tomate, o arroz e a água do cozimento. Tampe e cozinhe até o arroz ficar macio."]'::jsonb, '{"restrictions":["Peixe","Glúten"],"appliances":["Fogão"],"goals":["Refeição de família","Rico em proteína"]}'::jsonb),
  ('feijao-cenoura', 'Feijão ensopado com cenoura', 45, 2, true, '["Deixe o feijão de molho, descarte a água e cozinhe os grãos em água limpa até amaciarem.","Refogue cebola, tomate e cenoura. Misture ao feijão e cozinhe até a cenoura ficar macia."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Fogão"],"goals":["Refeição leve","Conforto e sabor"]}'::jsonb),
  ('ovos-tomate', 'Ovos cozidos no molho de tomate', 20, 2, true, '["Refogue a cebola, junte o tomate e o molho e deixe encorpar.","Abra quatro espaços no molho e quebre um ovo em cada um. Tampe e cozinhe até claras e gemas firmarem."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Glúten"],"appliances":["Fogão"],"goals":["Refeição prática","Rico em proteína"]}'::jsonb),
  ('omelete-brocolis', 'Omelete de brócolis', 18, 2, true, '["Cozinhe os floretes de brócolis até ficarem macios e pique.","Refogue a cebola, misture os ovos batidos com o brócolis e cozinhe até firmar dos dois lados."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Glúten"],"appliances":["Fogão"],"goals":["Refeição leve","Rico em proteína"]}'::jsonb),
  ('bolo-banana-aveia', 'Bolo de banana e aveia', 40, 2, true, '["Amasse a banana e misture com os ovos e a aveia. Unte uma forma pequena com o óleo.","Asse a 180 °C até a massa firmar e um palito sair limpo. Deixe amornar antes de cortar."]'::jsonb, '{"restrictions":["Peixe","Vegetariano"],"appliances":["Forno"],"goals":["Lanche caseiro","Conforto e sabor"]}'::jsonb),
  ('batata-doce-forno', 'Batata-doce e cenoura assadas', 40, 2, true, '["Corte os legumes em pedaços do mesmo tamanho e envolva com óleo.","Espalhe em uma assadeira e asse a 200 °C, virando na metade, até dourar e ficar macio."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Forno"],"goals":["Refeição leve","Diferente"]}'::jsonb),
  ('batata-doce-airfryer', 'Batata-doce rústica na air fryer', 25, 2, true, '["Lave a batata-doce e corte em palitos grossos. Seque e misture com óleo.","Asse em uma única camada a 190 °C, agitando o cesto no meio, até dourar e amaciar."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Air fryer"],"goals":["Lanche caseiro","Diferente"]}'::jsonb),
  ('brocolis-airfryer', 'Brócolis e tomate na air fryer', 18, 2, true, '["Separe o brócolis em floretes, corte o tomate em gomos e envolva os legumes com óleo.","Asse a 180 °C até dourar levemente, mexendo o cesto na metade do tempo."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Air fryer"],"goals":["Refeição leve","Diferente"]}'::jsonb),
  ('batata-doce-microondas', 'Batata-doce e cenoura no micro-ondas', 16, 2, true, '["Corte os legumes em cubos e coloque em recipiente próprio para micro-ondas com um pouco de água.","Cubra com tampa ventilada e cozinhe em intervalos, mexendo entre eles, até amaciar."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Micro-ondas"],"goals":["Refeição leve","Refeição prática"]}'::jsonb),
  ('mingau-microondas', 'Mingau de banana no micro-ondas', 8, 2, true, '["Misture leite e aveia em uma tigela alta própria para micro-ondas.","Aqueça em intervalos curtos, mexendo para evitar transbordamento. Junte a banana amassada quando engrossar."]'::jsonb, '{"restrictions":["Peixe","Vegetariano"],"appliances":["Micro-ondas"],"goals":["Lanche caseiro","Refeição prática"]}'::jsonb),
  ('lentilha-batata-doce', 'Sopa de lentilha e batata-doce', 40, 2, true, '["Refogue a cebola e junte a lentilha lavada, a cenoura e a batata-doce em cubos.","Cubra com água e cozinhe até amaciar. Amasse parte dos legumes para engrossar o caldo."]'::jsonb, '{"restrictions":["Peixe","Vegetariano","Vegano","Glúten"],"appliances":["Fogão"],"goals":["Refeição leve","Conforto e sabor"]}'::jsonb),
  ('panqueca-banana-aveia', 'Panqueca de banana e aveia', 18, 2, true, '["Amasse a banana, misture a aveia e os ovos e deixe hidratar alguns minutos.","Coloque pequenas porções em frigideira untada. Vire quando a borda firmar e cozinhe completamente o outro lado."]'::jsonb, '{"restrictions":["Peixe","Vegetariano"],"appliances":["Fogão"],"goals":["Lanche caseiro","Refeição prática"]}'::jsonb)
on conflict (id) do nothing;

